AudioDriver::SpeakerMode AudioDriver::get_speaker_mode_by_total_channels(int channels) const {
	switch (channels) {
		case 4:
			return SPEAKER_SURROUND_31;
		case 6:
			return SPEAKER_SURROUND_51;
		case 8:
			return SPEAKER_SURROUND_71;
	}

	// Default to STEREO
	return SPEAKER_MODE_STEREO;
}
